import com.google.gson.internal.UnsafeAllocator;

public class Exp {
  static abstract class Abs { int x; }
  interface Iface {}
  static class Ctor { static int count=0; int v=42; Ctor(){ count++; throw new RuntimeException("bad"); } }
  static class PrivCtor { private PrivCtor(){} }

  public static void main(String[] args) throws Exception {
    UnsafeAllocator ua = UnsafeAllocator.create();
    System.out.println("ua=" + ua);

    try {
      Ctor c = ua.newInstance(Ctor.class);
      System.out.println("Ctor created: v=" + c.v + " count=" + Ctor.count);
    } catch (Exception e) {
      System.out.println("Ctor failed: " + e);
    }

    try {
      Abs a = ua.newInstance(Abs.class);
      System.out.println("Abs created: " + a);
    } catch (Throwable e) {
      System.out.println("Abs failed: " + e);
    }

    try {
      Iface i = ua.newInstance(Iface.class);
      System.out.println("Iface created: " + i);
    } catch (Throwable e) {
      System.out.println("Iface failed: " + e);
    }

    try {
      Object o = ua.newInstance(null);
      System.out.println("null created: " + o);
    } catch (Throwable e) {
      System.out.println("null failed: " + e);
    }

    try {
      PrivCtor p = ua.newInstance(PrivCtor.class);
      System.out.println("PrivCtor created: " + p);
    } catch (Throwable e) {
      System.out.println("PrivCtor failed: " + e);
    }

    UnsafeAllocator ua2 = UnsafeAllocator.create();
    System.out.println("ua2 same class as ua? " + (ua.getClass() == ua2.getClass()));
  }
}
